.compass-root .compass svg{width:64px;height:64px}
.compass-root .sheet{position:relative;margin:20px 64px 0 128px;min-height:calc(100cqh - 148px)}
.compass-root .page{position:relative;z-index:2}
.compass-root .scenery{position:absolute;inset:0;width:100%;height:100%;z-index:1;pointer-events:none;overflow:visible}
.compass-root .sky{position:absolute;left:0;right:0;top:-5px;height:243px;z-index:0;pointer-events:none}
.compass-root .sky img{width:100%;height:100%;display:block}
.compass-root .today{padding-top:24px}
