.compass-root .habit-history{display:flex;margin-left:auto;align-items:center}
.compass-root .habit-history i{width:3px;height:3px;border-radius:50%;background:var(--ink)}
.compass-root .question-title{font-size:14px;line-height:24px;max-width:12em}
.compass-root .dial{width:100%;touch-action:none}
.compass-root .dial text{font:12px var(--mono);fill:var(--secondary)}
