.compass-root .journal{margin-top:31px}
.compass-root .journal-line{font-size:14px;line-height:26px;margin-bottom:10px;display:flex;gap:12px}
.compass-root .journal-line time{font-size:12px;line-height:26px;color:var(--secondary);flex-shrink:0}
.compass-root .line-form{display:flex;align-items:center;gap:12px;position:relative}
.compass-root .line-form input{border-bottom:1px solid var(--tick);width:100%;min-width:0;height:40px;padding:4px 0}
.compass-root .line-form .icon-button{flex-shrink:0}
.compass-root .icon-button{width:30px;min-height:34px;font-size:21px;line-height:1.3}
.compass-root .sky-interactions{position:relative;height:248px;pointer-events:none}
.compass-root .sky-interactions button{pointer-events:auto}
.compass-root .lighthouse-hit{position:absolute;right:20px;top:25px;cursor:pointer}
.compass-root .sky-empty{position:absolute;inset:0 160px 0 0;width:calc(100% - 160px);height:220px}
.compass-root .week-node{position:absolute;transform:translate(-50%,-50%);width:34px;height:34px;display:grid;place-items:center;font:12px var(--mono);color:var(--secondary)}
.compass-root .week-node::after{content:'';position:absolute;width:3px;height:3px;border-radius:50%;background:currentColor;bottom:-2px}
