.compass-root .goals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:32px;padding-right:18px}
.compass-root .goal{text-align:left;display:flex;align-items:center;align-self:start;flex-wrap:wrap;position:relative}
.compass-root .goal .resume{font:12px var(--mono);color:var(--secondary)}
