.compass-root .fold{position:absolute;right:0;top:0;width:24px;height:24px;border-top:1px solid var(--tick);border-right:1px solid var(--tick);clip-path:polygon(0 0,100% 0,100% 100%);background:none}
.compass-root .fold::after{content:'';position:absolute;right:0;top:11px;width:31px;height:1px;background:var(--tick);transform:rotate(45deg)}
