.compass-root .day-number.now{color:var(--now)}
.compass-root .unscheduled-icon{height:36px;margin-bottom:25px;display:flex;align-items:center}
.compass-root .unscheduled-icon svg{width:22px;height:22px}
.compass-root .plan-task{display:block;text-align:left;font-size:14px;position:relative;overflow-wrap:anywhere}
.compass-root .plan-task.done{color:var(--secondary);text-decoration:line-through;text-decoration-color:var(--tick)}
.compass-root .plan-task:hover{text-decoration:underline;text-underline-offset:5px}
.compass-root .day-column.drop-target{outline:1px dashed var(--secondary);outline-offset:5px}
.compass-root .schedule-editor{grid-column:1/-1;border-bottom:1px solid var(--line);padding:18px 0;display:flex;align-items:center;gap:24px}
