@keyframes obBob { 
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  30% { transform: translateY(-4px) rotate(1.1deg); }
  65% { transform: translateY(-1px) rotate(-0.8deg); }
}
@keyframes obDrift { 
  0%, 100% { transform: translateX(0px); }
  50% { transform: translateX(16px); }
}
@keyframes obDriftSlow { 
  0%, 100% { transform: translateX(0px); }
  50% { transform: translateX(-20px); }
}
@keyframes obSway { 
  0%, 100% { transform: rotate(-3.2deg); }
  50% { transform: rotate(3.2deg); }
}
@keyframes obNeedle { 
  0%, 100% { transform: rotate(-8deg); }
  28% { transform: rotate(6deg); }
  52% { transform: rotate(-3deg); }
  76% { transform: rotate(7deg); }
}
@keyframes obGlow { 
  0%, 100% { opacity: 0.55; transform: scale(0.92); }
  50% { opacity: 1; transform: scale(1.08); }
}
@keyframes obFlicker { 
  0%, 100% { transform: scale(1, 1); }
  20% { transform: scale(0.9, 0.82); }
  45% { transform: scale(1.06, 1.12); }
  70% { transform: scale(0.95, 0.9); }
}
@keyframes obPass { 
  0% { transform: translateX(-46px); }
  100% { transform: translateX(46px); }
}
@keyframes obTurn { 
  0%, 88% { transform: rotate(0deg); }
  96%, 100% { transform: rotate(180deg); }
}
@keyframes obDrain { 
  0% { transform: scaleY(1); }
  86%, 100% { transform: scaleY(0.06); }
}
@keyframes obFill { 
  0% { transform: scaleY(0.06); }
  86%, 100% { transform: scaleY(1); }
}
@keyframes obStreamOn { 
  0%, 84% { opacity: 1; }
  86%, 100% { opacity: 0; }
}
@keyframes obStream { 
  0% { stroke-dashoffset: 0; }
  100% { stroke-dashoffset: -8; }
}
@keyframes obWrite { 
  0% { transform: scaleX(0); opacity: 1; }
  45%, 80% { transform: scaleX(1); opacity: 1; }
  92% { transform: scaleX(1); opacity: 0; }
  100% { transform: scaleX(0); opacity: 0; }
}
@keyframes obQuill { 
  0%, 48%, 100% { transform: rotate(0deg) translateY(0px); }
  8% { transform: rotate(-4deg) translateY(2px); }
  16% { transform: rotate(2deg) translateY(-1px); }
  24% { transform: rotate(-3deg) translateY(2px); }
  32% { transform: rotate(2.5deg) translateY(0px); }
  40% { transform: rotate(-2deg) translateY(1px); }
}
@keyframes obTick { 
  0%, 48% { transform: scale(0); opacity: 0; }
  60%, 88% { transform: scale(1); opacity: 1; }
  100% { transform: scale(1); opacity: 0; }
}
@keyframes obArm { 
  0%, 100% { transform: rotate(-6deg); }
  50% { transform: rotate(7deg); }
}
@keyframes obGlint { 
  0%, 40%, 100% { opacity: 0; transform: scale(0.4) rotate(0deg); }
  55% { opacity: 1; transform: scale(1.25) rotate(45deg); }
  70% { opacity: 0; transform: scale(0.6) rotate(90deg); }
}
@keyframes obDash { 
  0% { opacity: 0.12; }
  8%, 66% { opacity: 1; }
  86%, 100% { opacity: 0.12; }
}
@keyframes obPing { 
  0% { transform: scale(1); opacity: 0.9; }
  100% { transform: scale(3.4); opacity: 0; }
}
@keyframes obLegL { 
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(5deg); }
}
@keyframes obLegR { 
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(-5deg); }
}
@keyframes obBeam { 
  0%, 100% { transform: rotate(-14deg); opacity: 0.65; }
  50% { transform: rotate(10deg); opacity: 1; }
}
@keyframes obFlutter { 
  0%, 100% { transform: scaleX(1) skewY(0deg); }
  25% { transform: scaleX(0.86) skewY(5deg); }
  60% { transform: scaleX(0.95) skewY(-4deg); }
}
@keyframes obShimmer { 
  0%, 100% { transform: scaleX(1); opacity: 0.7; }
  50% { transform: scaleX(0.86); opacity: 1; }
}
@keyframes obGlide { 
  0%, 100% { transform: translate(0px, 0px); }
  50% { transform: translate(18px, -5px); }
}
@keyframes obFlap { 
  0%, 100% { transform: scaleY(1); }
  50% { transform: scaleY(-0.35); }
}
@keyframes obJump { 
  0%, 70% { opacity: 0; transform: translate(0px, 0px) rotate(0deg); }
  73% { opacity: 1; transform: translate(-5px, -12px) rotate(-28deg); }
  79% { opacity: 1; transform: translate(-13px, -18px) rotate(0deg); }
  85% { opacity: 1; transform: translate(-21px, -8px) rotate(28deg); }
  89%, 100% { opacity: 0; transform: translate(-24px, 0px) rotate(34deg); }
}
