.compass-root .task-view-sort-controls button{width:19px;min-height:24px;font-size:20px;color:var(--secondary)}
.compass-root .task-view-sort-controls button:disabled{opacity:.25;cursor:default}

/* Quarterly goal names occupy their own rows, never share a map coordinate. */
.compass-root #review .quarter-sheet .q-voyage{display:flex;flex-direction:column;margin:12px auto 4px}
.compass-root #review .quarter-sheet .q-goals{position:static;order:-1;display:flex;flex-wrap:wrap;justify-content:center;gap:8px 24px;margin-bottom:8px}
