/* Search returns an explicit, actionable list rather than an invisible filter. */
.compass-root #library .lib-search-results{position:absolute;z-index:90;max-height:min(420px,65cqh);display:flex;flex-direction:column;background:var(--paper);border:1px solid var(--tick);border-radius:9px;box-shadow:0 6px 20px #0002;padding:10px;overflow:hidden;color:var(--ink)}
