/* Completed project tasks remain readable at the bottom. */
.compass-root #projects .project-task-list>.project-task-row.is-completed{opacity:.48}
.compass-root #projects .project-task-row.is-completed>[data-p2="open-object"]{text-decoration:line-through;text-decoration-thickness:1px;color:var(--secondary)}
.compass-root #projects .project-task-row.is-completed time{color:var(--secondary);text-decoration:none}
/* Per-record return and unambiguous favorite state. */
.compass-root #library .lib-record-heading{display:flex;align-items:flex-start;gap:8px;min-width:0;flex:1}
.compass-root #library .lib-record-heading>div{min-width:0}
.compass-root #library .lib-record-back{display:inline-flex;align-items:center;justify-content:center;flex:none;width:22px;min-width:22px;min-height:28px;padding:0;margin-top:1px;background:none;border:0;box-shadow:none;color:var(--ink)}
.compass-root #library .lib-favorite.is-favorite{color:#1C2A35}
.compass-root #library .lib-favorite.is-favorite svg{fill:none}

/* Formatting tools explain themselves on hover and keyboard focus. */
.compass-root .task-sheet-tools{overflow:visible;position:relative;z-index:12}
.compass-root .task-sheet-tools [data-format-tip]{position:relative}
.compass-root .task-sheet-tools [data-format-tip]:is(:hover,:focus-visible)::after{content:attr(data-format-tip);position:absolute;top:calc(100% + 7px);left:50%;transform:translateX(-50%);width:max-content;max-width:200px;padding:4px 7px;border-radius:4px;background:var(--paper);color:var(--ink);font:12px/1.5 var(--sans);white-space:nowrap;box-shadow:0 2px 7px #0002;z-index:120;pointer-events:none}

/* Compact association controls beside the task title. */
.compass-root #tasks .task-title-relations{display:inline-flex;align-items:center;gap:3px;flex:none;margin-left:auto;padding-top:1px}
.compass-root #tasks .task-title-relations>button{display:inline-flex;align-items:center;justify-content:center;width:26px;min-width:26px;height:30px;padding:0;border:0;border-radius:5px;background:none;box-shadow:none;color:var(--secondary)}
.compass-root #tasks .task-title-relations>button svg{width:18px!important;height:18px!important;flex:none}
.compass-root #tasks .task-title-relations>button:is(:hover,:focus-visible){color:var(--ink);background:color-mix(in srgb,var(--ink) 7%,transparent)}
.compass-root #tasks .task-sheet-titlebar .task-sheet-mode{margin-left:0}
.compass-root .pd-tasks .project-task-add{position:relative}
.compass-root .pd-tasks .project-task-add .task-suggest{position:absolute;z-index:47;width:220px;padding:8px 10px;bottom:calc(100% + 4px);top:auto}
.compass-root .pd-tasks .project-task-add .task-suggest button{display:block;width:100%;padding:4px 6px;text-align:left;cursor:pointer}
.compass-root .pd-tasks .project-task-add .task-suggest button[aria-selected="true"]{background:color-mix(in srgb,var(--ink) 6%,transparent);font-weight:600}
.compass-root #tasks .task-md-hint{display:flex;flex-wrap:wrap;gap:4px 16px;margin:12px 0 0;padding:0;font-size:12px;line-height:1.5;color:var(--muted)}
.compass-root #tasks .task-md-hint b{display:inline-block;min-width:1.2em;margin-right:2px;text-align:center;font-family:var(--mono,monospace);font-weight:600;color:var(--ink)}
.compass-root #tasks .task-md-hint + .task-md-host{margin-top:4px}
.compass-root #tasks .task-slash{scrollbar-width:thin;overscroll-behavior:contain}
.compass-root #tasks .task-sheet-tools [data-format-tip]:is(:hover,:focus-visible)::after{top:auto;bottom:calc(100% + 4px);padding:0;border-radius:0;background:none;box-shadow:none;color:var(--ink);font-size:12px;text-shadow:0 0 3px var(--paper),0 0 5px var(--paper),0 0 8px var(--paper)}
.compass-root #brain .brain-node.is-icon-only > svg{width:18px!important;height:18px!important}
.compass-root #brain .graph-node.brain-node.is-icon-only{padding:0;gap:0;justify-content:center;background:none;border:0;box-shadow:none;display:grid;place-items:center;height:30px;min-height:30px;cursor:pointer}
.compass-root #brain .brain-node.is-icon-only:is(:hover,:focus-visible){background:color-mix(in srgb,var(--ink) 7%,transparent);border-radius:50%;outline:none}
.compass-root #brain .brain-node.is-icon-only[aria-pressed="true"]{background:color-mix(in srgb,var(--tick) 30%,var(--paper));border-radius:50%}
.compass-root #brain .graph-node.brain-node.is-two{padding-top:8px;padding-bottom:8px}
.compass-root #brain .brain-node .node-name{text-align:center;text-wrap:balance;flex:0 1 auto;word-break:normal;overflow-wrap:anywhere}
.compass-root #tasks .task-sheet-subtask{display:inline-flex;align-items:center;justify-content:center;flex:none;width:26px;min-width:26px;height:30px;padding:0;border:0;border-radius:5px;background:none;box-shadow:none;color:var(--secondary)}
.compass-root #tasks .task-sheet-subtask svg{width:18px!important;height:18px!important;flex:none}
.compass-root #tasks .task-sheet-subtask:is(:hover,:focus-visible){color:var(--ink);background:color-mix(in srgb,var(--ink) 7%,transparent);outline:none}
.compass-root #brain{height:calc(100cqh - 148px + 44px)}
.compass-root #sheet:has(> #brain:not([hidden])){max-height:calc(100cqh - 128px);overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}
.compass-root #brain .brain-rank{max-height:calc(100cqh - 298px)}
.compass-root #brain .brain-chip-note{position:absolute;left:2px;top:54px;z-index:6;margin:0;max-width:calc(100% - 420px);overflow:visible;font-size:12px;line-height:1.4;color:var(--muted);white-space:normal;text-overflow:clip;pointer-events:none}
.compass-root #brain .brain-plain-list .brain-list-head{grid-column:1 / -1;display:flex;align-items:baseline;gap:8px;margin:14px 0 4px;padding:0 0 4px;border-bottom:1px solid var(--line);font:500 15px var(--serif);color:var(--ink)}
.compass-root #brain .brain-plain-list .brain-list-head:first-child{margin-top:0}
.compass-root #brain .brain-plain-list .brain-list-head span{font-size:12px;color:var(--secondary)}
.compass-root #brain .brain-node[data-kind="task"] .node-name{font-size:12px}
.compass-root #brain .brain-node.is-subtask .node-name{color:color-mix(in srgb,var(--ink) 52%,transparent)}
.compass-root #brain .brain-node.is-subtask > svg:not(.hand-popup-frame){opacity:.5}
@container compass (max-width: 1320px){.compass-root #brain .brain-node[data-kind="task"] .node-name{font-size:11.5px}}
.compass-root #brain.is-list .brain-plain-list.hand-panel{position:relative;left:auto;right:auto;top:auto;bottom:auto;margin:0 0 56px;max-height:none;overflow:visible}
.compass-root #brain.is-list{height:auto;min-height:calc(100cqh - 148px + 44px);box-sizing:border-box;padding-top:92px}
.compass-root #brain .brain-node[data-kind="task"]:not(.is-subtask) .node-name{color:color-mix(in srgb,var(--ink) 78%,transparent)}
.compass-root #brain .brain-node[data-kind="task"]:not(.is-subtask) > svg:not(.hand-popup-frame){opacity:.8}
.compass-root #brain .brain-plain-list .brain-done-toggle{grid-column:1 / -1;display:flex;align-items:baseline;gap:8px;margin:10px 0 2px;padding:2px 0;font-size:13px;color:var(--secondary);text-align:left;cursor:pointer}
.compass-root #brain .brain-plain-list .brain-done-toggle .mono{font-size:12px}
.compass-root #brain .brain-plain-list .brain-done-toggle:is(:hover,:focus-visible){color:var(--ink);outline:none}
.compass-root #brain .brain-plain-list .is-done-task > span{text-decoration:line-through;text-decoration-thickness:1px;color:var(--secondary)}
.compass-root #brain .brain-cluster.is-foldable{pointer-events:auto;cursor:pointer}
.compass-root #brain .brain-cluster.is-foldable:is(:hover,:focus-visible){background:color-mix(in srgb,var(--ink) 6%,var(--paper));outline:none}
.compass-root #brain .brain-cluster.is-folded{color:var(--secondary)}
.compass-root #brain :is(.brain-fold-caret,.brain-fold-count){font-size:12px;color:var(--secondary)}
.compass-root #brain .brain-top{position:sticky;top:0;height:0;z-index:7}
.compass-root #brain.is-list .brain-top{margin-top:-92px}
/* 思索页天空：背景往下延长，完全盖住最下面的地平线，再从线下面渐变成白色；整体略高一点 */
.compass-root #sky{height:306px}
.compass-root #thought .sky-interactions{height:282px}
/* 目标卡片：名称、进度条、日期始终在同一行；放不下时先压缩进度条，再把名称截成省略号，不再换行 */
.compass-root .goal{flex-wrap:nowrap}
.compass-root .goal .goal-name{flex:0 1 auto;min-width:3em}
.compass-root .goal .smear-progress{flex:0 1 126px;min-width:56px}
.compass-root .goal :is(.goal-due,.goal-done,.resume){flex:none;white-space:nowrap}
/* 想法卡片：没有标签时用小短横代替，点开选已有标签或新建 */
.compass-root .idea-card-meta .idea-tag-add{display:inline-flex;align-items:center;justify-content:center;min-width:24px;height:20px;padding:0 6px;margin-left:10px;background:none;border:0;box-shadow:none;font:13px var(--mono);line-height:1;color:var(--secondary);cursor:pointer}
.compass-root .idea-card-meta .idea-tag-add:is(:hover,:focus-visible,[aria-expanded="true"]){color:var(--ink);background:color-mix(in srgb,var(--ink) 7%,transparent);border-radius:4px;outline:none}
.compass-root .idea-tag-picker{display:flex;flex-direction:column;gap:8px;margin:2px 0 10px;max-width:420px}
.compass-root .idea-tag-picker .idea-tag-input{width:100%;padding:3px 0 5px;background:none;border:0;border-bottom:1px solid var(--line);outline:none;box-shadow:none;font:inherit;font-size:14px;color:var(--ink)}
.compass-root .idea-tag-picker .idea-tag-input:focus{border-bottom-color:var(--tick)}
.compass-root .idea-tag-options{display:flex;flex-wrap:wrap;gap:6px}
.compass-root .idea-tag-options button{padding:2px 10px;border:1px solid var(--line);border-radius:12px;background:none;box-shadow:none;font-size:12.5px;color:var(--ink);cursor:pointer}
.compass-root .idea-tag-options button:is(:hover,:focus-visible,[aria-selected="true"]){background:color-mix(in srgb,var(--ink) 8%,transparent);outline:none}
.compass-root .idea-tag-options button.is-new{border-style:dashed;color:var(--secondary)}
.compass-root .idea-tag-current{display:flex;flex-wrap:wrap;gap:6px}
.compass-root .idea-tag-current button{display:inline-flex;align-items:center;gap:6px;padding:2px 8px 2px 10px;border:1px solid var(--tick);border-radius:12px;background:none;box-shadow:none;font-size:12.5px;color:var(--ink);cursor:pointer}
.compass-root .idea-tag-current button span{font-size:13px;color:var(--secondary)}
.compass-root .idea-tag-current button:is(:hover,:focus-visible){background:color-mix(in srgb,var(--ink) 8%,transparent);outline:none}
.compass-root .idea-tag-options button[aria-pressed="true"]{border-color:var(--tick);color:var(--ink)}
.compass-root .idea-card-tags button{cursor:pointer}
/* 复盘页航海日志：让文字区高度被框住（超出由脚本缩小字号），不再把文字顶出框外 */
.compass-root #review .q-quote blockquote{min-height:0;overflow:hidden}
/* 知识库顶部的「项目筛选」标签：和旁边的 Zotero、知识库按钮一样的手绘框，用项目图标代替「项目」二字 */
.compass-root #library .lib-project-chip{display:inline-flex;align-items:center;gap:7px;height:34px;padding:0 14px;border:0;border-radius:17px;font-size:13px;color:var(--ink);background:var(--paper);white-space:nowrap;flex:none;position:relative}
.compass-root #library .lib-project-chip svg:not(.hand-popup-frame){width:16px!important;height:16px!important;flex:none}
.compass-root #library .lib-project-chip i{font-style:normal;color:var(--secondary)}
.compass-root #library .lib-project-chip:is(:hover,:focus-visible) i{color:var(--ink)}
/* 今日聚焦：点标题换聚焦的任务 */
.compass-root button.focus-section-pick{background:none;border:0;padding:0;box-shadow:none;font:inherit;color:inherit;text-align:left;cursor:pointer}
.compass-root button.focus-section-pick:is(:hover,:focus-visible) > span{text-decoration:underline;text-underline-offset:4px;outline:none}
.compass-root .focus-picker{margin:0 0 14px}
/* 知识库详情的摘要、笔记、标注、相关：阅读模式 */
.compass-root .lib-reading{background:none;padding:0;color:var(--ink);font-size:13.5px;line-height:1.8}
.compass-root .lib-reading > :first-child{margin-top:0}
.compass-root .lib-reading > :last-child{margin-bottom:0}
.compass-root .lib-reading p{margin:0 0 .7em}
.compass-root .lib-reading :is(ul,ol){margin:0 0 .7em;padding-left:1.4em}
.compass-root .lib-reading li{margin:.15em 0}
.compass-root .lib-reading blockquote{margin:.4em 0 .7em;padding:0 0 0 12px;border-left:2px solid var(--tick);color:var(--secondary)}
.compass-root .lib-reading :is(h1,h2,h3,h4){margin:.8em 0 .4em;font-size:1em;font-weight:600}
.compass-root .lib-reading a{color:var(--now);text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.compass-root .lib-marks li > .lib-reading{font-size:13px}
/* 知识库笔记输入框下面的格式按钮 */
.compass-root .lib-note-bar .lib-fmt{display:inline-flex;align-items:center;justify-content:center;width:28px;height:26px;padding:0;margin:0;border:0;border-radius:5px;background:none;box-shadow:none;font-size:13px;color:var(--secondary);cursor:pointer}
.compass-root .lib-note-bar .lib-fmt:is(:hover,:focus-visible){color:var(--ink);background:color-mix(in srgb,var(--ink) 8%,transparent);outline:none}
.compass-root .lib-note-bar .lib-fmt[data-lib-fmt="b"]{font-weight:700}
.compass-root .lib-note-bar .lib-fmt[data-lib-fmt="i"]{font-style:italic}
/* 知识库详情阅读模式里的标题：最大的一级标题也不超过文件标题（22px），逐级变小 */
.compass-root .lib-record .lib-reading :is(h1,h2,h3,h4,h5,h6){margin:.9em 0 .4em!important;line-height:1.4!important;font-weight:600!important;font-family:var(--serif)!important}
.compass-root .lib-record .lib-reading h1{font-size:20px!important}
.compass-root .lib-record .lib-reading h2{font-size:18px!important}
.compass-root .lib-record .lib-reading h3{font-size:16.5px!important}
.compass-root .lib-record .lib-reading :is(h4,h5,h6){font-size:15px!important}
.compass-root .lib-record .lib-reading :is(h1,h2,h3,h4,h5,h6):first-child{margin-top:0!important}
/* 今日页「想到了什么？」输入行：固定在右下角，不随页面上下滚动（位置和宽度由脚本对齐右边那一列） */
.compass-root #today #journal-form{position:fixed;z-index:20;bottom:14px;margin:0;padding:6px 0 4px;background:var(--paper);box-sizing:border-box}
.compass-root #today .today-subsection[data-today-group="journal"]{padding-bottom:52px}

/* 页面里所有渲染出来的 Markdown 标题（想法正文、知识库阅读）：最大的一级标题也不超过页面标题，逐级变小 */
.compass-root .markdown-rendered :is(h1,h2,h3,h4,h5,h6){margin:.9em 0 .4em!important;line-height:1.4!important;font-weight:600!important;font-family:var(--serif)!important}
.compass-root .markdown-rendered h1{font-size:20px!important}
.compass-root .markdown-rendered h2{font-size:18px!important}
.compass-root .markdown-rendered h3{font-size:16.5px!important}
.compass-root .markdown-rendered :is(h4,h5,h6){font-size:15px!important}

/* 知识库摘要只显示第一段、关键信息每条最多两行，没显示完的有「展开 / 收起」 */
.compass-root .lib-reading[data-lib-fold="para"]:not(.is-open){display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.compass-root .lib-record .lib-fold-toggle + h4{margin-top:6px}
.compass-root .lib-points .lib-point{flex:1;min-width:0}
.compass-root .lib-points .lib-point-text{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}
.compass-root .lib-points li.is-open .lib-point-text{display:block;-webkit-line-clamp:unset;overflow:visible}
.compass-root .lib-fold-toggle{display:block;margin:2px 0 0;padding:2px 0 1px;border:0;background:none;box-shadow:none;font-size:12px;line-height:1.5;color:var(--secondary);cursor:pointer}
.compass-root .lib-fold-toggle:is(:hover,:focus-visible){color:var(--ink);outline:none}

/* 输入 # / @ 时弹出的已有标签 / 人物列表（记录框、想法输入框） */
.compass-root .tl-suggest{position:fixed;z-index:200;width:230px;max-height:260px;overflow-y:auto;padding:8px 10px;box-sizing:border-box;scrollbar-width:thin}
.compass-root .tl-suggest button{display:block;width:100%;padding:5px 6px;border:0;background:none;box-shadow:none;text-align:left;font:inherit;font-size:14px;line-height:1.45;color:var(--ink);cursor:pointer}
.compass-root .tl-suggest button[aria-selected="true"]{background:color-mix(in srgb,var(--ink) 7%,transparent);font-weight:600}

/* 任务正文（Obsidian 自带编辑器）和其他嵌在页面里的编辑器 / 预览：标题也不超过页面标题（任务标题 20px），逐级变小 */
.compass-root .cm-editor,.compass-root .markdown-preview-view{--h1-size:18px;--h2-size:17px;--h3-size:16px;--h4-size:15px;--h5-size:15px;--h6-size:15px}
.compass-root :is(.cm-editor,.markdown-preview-view) :is(.cm-header-1,.HyperMD-header-1,h1){font-size:18px!important;line-height:1.5!important}
.compass-root :is(.cm-editor,.markdown-preview-view) :is(.cm-header-2,.HyperMD-header-2,h2){font-size:17px!important;line-height:1.5!important}
.compass-root :is(.cm-editor,.markdown-preview-view) :is(.cm-header-3,.HyperMD-header-3,h3){font-size:16px!important;line-height:1.5!important}
.compass-root :is(.cm-editor,.markdown-preview-view) :is(.cm-header-4,.cm-header-5,.cm-header-6,.HyperMD-header-4,.HyperMD-header-5,.HyperMD-header-6,h4,h5,h6){font-size:15px!important;line-height:1.5!important}


/* 想法卡片：标题和正文之间的间隔缩短一半 */
.compass-root .idea-card .idea-detail{padding-top:4px}
.compass-root .idea-card .idea-excerpt{margin-top:4px}
.compass-root .idea-card .idea-reading > :first-child{margin-top:4px!important}

/* 知识库详情的标题：点一下就能改名（书籍、文献都一样） */
.compass-root #library :is(.lib-card,.lib-record) h3 .lib-inline-value{cursor:text;text-align:left;display:inline;font:inherit}
.compass-root #library :is(.lib-card,.lib-record) h3 .lib-inline-value:is(:hover,:focus-visible){text-decoration:underline dotted;text-underline-offset:5px;outline:none}
.compass-root #library :is(.lib-card,.lib-record) h3 .lib-inline-editor{margin:0}

/* 知识库详情的正文区：不整条丢掉压在横线上的内容，而是靠近横线的那一行字渐渐变淡，到横线以下完全消失 */
.compass-root .lib-record-body[data-r33-more="true"]{-webkit-mask-image:linear-gradient(#000 calc(var(--r34-cut,100%) - 34px),transparent var(--r34-cut,100%));mask-image:linear-gradient(#000 calc(var(--r34-cut,100%) - 34px),transparent var(--r34-cut,100%))}

/* 海图视图：每个阶段点名字（或绳结）折叠 / 展开；内容多了整页自动加长，可以上下滚动 */
.compass-root button.lib-depth{pointer-events:auto;cursor:pointer;background:none;border:0;box-shadow:none;padding:0;margin:0;text-align:right;color:inherit}
.compass-root button.lib-depth:is(:hover,:focus-visible) b{text-decoration:underline dotted;text-underline-offset:4px}
.compass-root button.lib-depth:focus-visible{outline:none}
.compass-root .lib-depth .lib-fold-mark{font-style:normal;font-size:10px;margin-left:5px;color:var(--secondary)}
.compass-root #sheet:has(> #library[data-library-view="sea"]:not([hidden])){max-height:calc(100cqh - 128px);overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}

/* 海图视图：「读完」「已泛读」「已精读」里往年读完的，按年份挂小绳结 */
.compass-root .lib-year-btn b{font:400 12.5px/1.3 var(--serif);color:var(--ink)}
.compass-root .lib-year-btn span{font-size:10px}
/* 年份小绳结的标签：年份和本数写在一行，并让出阶段名下面那行深度范围的位置 */
.compass-root .lib-year-btn{flex-direction:row;align-items:baseline;gap:6px}

/* 读书笔记的小箭头（书签纸上、锚图标的右边）；同一周读完那一行的「+N / 收起」 */
.compass-root #library .lib-tag .lib-notes-arrow{flex:none;width:22px;height:26px;margin-right:2px;padding:0;border:0;background:none;box-shadow:none;color:inherit;font-size:12px;line-height:26px;cursor:pointer}
.compass-root #library .lib-tag .lib-notes-arrow:is(:hover,:focus-visible){outline:none;opacity:.7}
.compass-root .lib-row-toggle{position:absolute;z-index:4;height:20px;padding:0 6px;border:0;background:none;box-shadow:none;font:12px/20px var(--serif);color:var(--secondary);cursor:pointer;white-space:nowrap}
.compass-root .lib-row-toggle:is(:hover,:focus-visible){color:var(--ink);outline:none}

/* 海图视图的纸签：书名写在一行里（宽度已按最长的书名算好），万一还放不下就用省略号 */
.compass-root #library .lib-tag .paper-title > span{display:block;white-space:nowrap;-webkit-line-clamp:unset;overflow:hidden;text-overflow:ellipsis}

/* 季度页：最下面一排内容多了，这一排加高，卡片区在页面里面上下滚动（上面的「日 周 季」、下面的风景都不动，见 fitQuarter） */
.compass-root #review[data-q-grow] .quarter-sheet{overflow-y:auto;overflow-x:hidden;scrollbar-width:thin}
.compass-root #review[data-q-grow] .quarter-sheet .q-grid{flex:0 0 auto;height:var(--q-grid-h);grid-template-rows:minmax(0,1fr) minmax(0,1fr) var(--q-row3)}

/* 季度页顶上的「2026 · 第 4 季」：年份和季度各是一个滚轮（鼠标放上去，上下露出前一个 / 后一个，滚轮或点它就能换） */
.compass-root #review .q-picks{display:inline-flex;align-items:center;gap:6px}
.compass-root #review .q-pick{position:relative;display:inline-block;padding:0 8px;border-radius:10px;cursor:ns-resize;outline:none}
.compass-root #review .q-pick b{font-weight:inherit}
.compass-root #review .q-pick:is(:hover,:focus-visible){background:color-mix(in srgb,var(--ink) 6%,transparent)}
.compass-root #review .q-step{position:absolute;left:50%;transform:translateX(-50%);padding:0;border:0;background:none;box-shadow:none;font:400 13px/1 var(--serif);color:var(--secondary);white-space:nowrap;opacity:0;pointer-events:none;cursor:pointer}
.compass-root #review .q-step-up{bottom:100%;margin-bottom:2px}
.compass-root #review .q-step-down{top:100%;margin-top:2px}
.compass-root #review .q-pick:is(:hover,:focus-within) .q-step{opacity:.6;pointer-events:auto}
.compass-root #review .q-step:hover{opacity:1!important;color:var(--ink)}
.compass-root #review .log-day-turn[disabled]{opacity:.25;cursor:default}

/* 读书笔记那一块：每条名字之间的间隔 = 1.25 倍行距（名字自己换行就是正常 1 倍行距），不再每条固定一个高度 */
.compass-root #library .lib-note-branch ul{--lh:19.5px;margin-top:6px}
.compass-root #library .lib-note-branch li,.compass-root #library .lib-note-tree li{display:block;min-height:0;padding:0;margin:0 0 calc(var(--lh,19.5px) * .25)}
.compass-root #library .lib-note-branch li:last-child,.compass-root #library .lib-note-tree li:last-child{margin-bottom:0}
.compass-root #library .lib-note-branch li:before,.compass-root #library .lib-note-tree li:before{top:calc(var(--lh,19.5px) / 2)}
.compass-root #library .lib-note-leaf{font-size:13px;line-height:1.5}

/* Separate calendar capture and upcoming schedule list. */
.compass-root #capture-schedule:not([hidden]){display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px;margin:10px 0}
.compass-root #capture-schedule label{display:flex;flex-direction:column;gap:4px;font-size:12px;color:var(--secondary)}
.compass-root #capture-schedule input{width:100%;min-width:0}
.compass-root #capture-schedule small{grid-column:1/-1;font-size:11px;line-height:1.5;color:var(--secondary)}
.compass-root .schedule-list-heading{display:flex;align-items:center;justify-content:space-between;margin:0 0 15px;font-size:18px}
.compass-root .schedule-list-row{display:flex;align-items:center;gap:16px;width:100%;padding:14px 4px;border:0;border-bottom:1px solid var(--line);border-radius:0;box-shadow:none;background:none;text-align:left}
.compass-root .schedule-list-row time{flex:none;font:12px/1.7 var(--mono);color:var(--secondary)}
.compass-root .schedule-list-row>span{font-size:15px;overflow-wrap:anywhere}
.compass-root .schedule-explanation{padding:10px 16px;font-size:14px;line-height:1.8}
.compass-root .overdue-original-date{display:block;color:var(--now);font:10px/1.5 var(--sans)}

/* Separate title and body when capturing an idea. */
.compass-root #capture #capture-idea-content:not([hidden]){margin-top:10px;min-height:90px;font-size:13px;line-height:1.7}
.compass-root #capture #capture-idea-content[hidden]{display:none!important}

/* The thought composer has a separate title and content field. */
.compass-root #idea-form #idea-content-input{display:block;width:100%;box-sizing:border-box;min-height:88px;max-height:240px;margin:8px 0;padding:8px 0;resize:vertical;overflow-y:auto;border:0;border-bottom:1px solid var(--line);border-radius:0;box-shadow:none;background:transparent;color:var(--ink);font:14px/1.8 var(--sans)}
.compass-root #idea-form #idea-content-input::placeholder{color:var(--secondary);opacity:.65}

/* Week planning completion controls share the task completion action. */
.compass-root #thought .plan-task button.pt-mark{appearance:none;display:block;box-sizing:border-box;padding:0;min-width:0;min-height:0;background:transparent;box-shadow:none;cursor:pointer;position:relative;overflow:visible}
.compass-root #thought .plan-task button.pt-mark::before{content:"";position:absolute;inset:-6px;border-radius:50%}
.compass-root #thought .plan-task button.pt-mark:hover{border-color:var(--ink);background:rgba(104,123,131,.12)}
.compass-root #thought .plan-task button.pt-mark:focus-visible{outline:2px solid var(--ink);outline-offset:4px}
.compass-root #thought .plan-task.done{opacity:.5}

.compass-root #review .review-day-edit{margin-left:auto;padding:2px 5px;font-size:11px;color:var(--secondary);background:transparent;border:0;box-shadow:none;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.compass-root #review .review-score-edit{padding:0;background:transparent;border:0;box-shadow:none;color:var(--secondary);text-align:right;cursor:pointer;font:inherit}
.compass-root #review button.review-habit-edit{padding:0;background:transparent;border:0;box-shadow:none;color:inherit;font:inherit;cursor:pointer}
.compass-root #review .review-day-edit:hover,.compass-root #review .review-score-edit:hover{color:var(--ink)}
.compass-root #review .review-day-edit:focus-visible,.compass-root #review .review-score-edit:focus-visible,.compass-root #review .review-habit-edit:focus-visible{outline:1px solid var(--secondary);outline-offset:3px}

/* Keep content's breathing room inside the scroller so its thumb reaches the paper edge. */
.compass-root #sheet{margin-right:0;padding-right:64px;box-sizing:border-box}
@container compass (max-width:1320px){.compass-root #sheet{padding-right:48px}}
@container compass (max-width:999px){.compass-root #sheet{padding-right:32px}}
.compass-root #sheet::-webkit-scrollbar-thumb{border-right:0!important}

/* Center the navigation within the left gutter and spread all entries over its height. */
.compass-root .rail{left:0;top:24px;bottom:24px;width:128px;justify-content:space-between;gap:8px}
.compass-root .rail #modules{display:contents}
.compass-root .rail .module{width:80px;flex:0 0 auto;height:clamp(48px,7cqh,68px);min-height:0;gap:6px;font-size:13px}
.compass-root .rail .module .nav-icon{width:26px;height:26px;flex:none}
.compass-root .rail .module.settings{margin-top:0}
@container compass (max-width:1320px){.compass-root .rail{width:112px}}
@container compass (max-width:999px){.compass-root .rail{width:96px}}
@container compass (max-height:640px){
  .compass-root .rail{top:16px;bottom:16px;gap:4px}
  .compass-root .rail .module{height:clamp(38px,7cqh,48px);font-size:12px;gap:4px}
  .compass-root .rail .module .nav-icon{width:23px;height:23px}
}

.compass-root .schedule-list-row>span small{display:block;margin-top:3px;font-size:12px;color:var(--secondary)}
.compass-root .schedule-people,.modal .schedule-people{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.compass-root .schedule-person,.modal .schedule-person{padding:2px 10px;border:1px solid var(--line,var(--background-modifier-border));border-radius:999px;background:none;font-size:12px;box-shadow:none;cursor:pointer}
.compass-root .schedule-person[aria-pressed="true"],.modal .schedule-person[aria-pressed="true"]{background:var(--interactive-accent,#4a6);color:var(--text-on-accent,#fff);border-color:transparent}
.compass-root #capture-schedule .capture-schedule-wide{grid-column:1/-1}
.compass-root #capture-schedule select{width:100%;min-width:0}
/* 已划线（已采用 / 搁置）的想法：紧凑成一行 */
.compass-root .idea-card.idea-settled{padding-top:5px;padding-bottom:5px;margin-bottom:0}
.compass-root .idea-card.idea-settled .idea-card-title{line-height:1.5;padding-top:0;padding-bottom:0}
.compass-root .idea-card.idea-settled .idea-card-star,.compass-root .idea-card.idea-settled .idea-project-link{top:50%;transform:translateY(-50%)}

.compass-root .linked-schedules{display:flex;flex-direction:column;min-width:0}
.compass-root .linked-schedules .schedule-linked-row{padding:7px 2px;gap:12px;font-size:14px}
.compass-root .linked-schedules .schedule-linked-row.is-past{opacity:.55}
.compass-root .pd-sub-schedules{display:flex;justify-content:space-between;align-items:baseline;margin-top:18px}
.compass-root .goal-schedules{align-items:flex-start}

.compass-root #projects .pd-stations .project-progress-list > button.pd-station{grid-template-columns:18px 1fr auto auto}
.compass-root .pd-station-edit{display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:4px;opacity:0;color:var(--secondary);cursor:pointer}
.compass-root .pd-station:hover .pd-station-edit,.compass-root .pd-station:focus-within .pd-station-edit,.compass-root .pd-station-edit:focus{opacity:.8}
.compass-root .pd-station-edit:hover{opacity:1;background:color-mix(in srgb,var(--tick) 25%,transparent)}
.compass-root .pd-station-edit svg{width:13px!important;height:13px!important;background:none!important}

.compass-root .pd-link-toggle{display:inline-flex;align-items:center;justify-content:center;padding:0;border:0;background:none;box-shadow:none;cursor:pointer;flex:none}
.compass-root .pd-link-toggle svg{width:18px!important;height:18px!important}
.compass-root .pd-fold-mark{font-size:11px;color:var(--secondary)}
